import pathlib
data_dir = pathlib.Path("data_small/Training_Handwritten_marathi_Character_Fusion/Data_set")

# Get all valid image files
image_file_paths = []
valid_extensions = {'.jpg', '.jpeg', '.png', '.gif', '.bmp', '.JPG', '.JPEG', '.PNG', '.GIF', '.BMP'}

for class_name in sorted(os.listdir(data_dir)):
    class_path = os.path.join(data_dir, class_name)
    if os.path.isdir(class_path):
        for file in os.listdir(class_path):
            file_path = os.path.join(class_path, file)
            ext = os.path.splitext(file)[1]
            if ext in valid_extensions:
                image_file_paths.append((file_path, class_name))

# Filter valid images by verifying they can be read
valid_file_pairs = []
for file_path, class_name in image_file_paths:
    try:
        img = tf.io.read_file(file_path)
        decoded = tf.image.decode_image(img, channels=3, expand_animations=False)
        valid_file_pairs.append((file_path, class_name))
    except:
        print(f"Skipping invalid image: {file_path}")

print(f"Total valid images: {len(valid_file_pairs)} out of {len(image_file_pairs)}")"}

